#if UNITY_EDITOR
using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;
namespace TotsuDan.MapEditor {
// 任意の描画専用補正。CliffFitsMeshV1の適用後に呼ぶ。Colliderと旧保存データは変更しない。
public static class CaveWallVisualsV1 {
 [Serializable]public class Geometry {public float[] positions,normals,colors,uvs;public int[] triangles;}
 [Serializable]public class Model {public string id,type,sourceSha256;public Geometry render;}
 [Serializable]public class Entry {public string instanceId,type,model;public bool fitted,replaceCollider;public float[] matrix,instanceTint;}
 [Serializable]public class Document {public string format;public int formatVersion;public Model[] models;public Entry[] instances;}
 public static Document Read(string json){var d=JsonUtility.FromJson<Document>(json);if(d==null||d.format!="cave-wall-visuals"||d.formatVersion!=1||d.models==null||d.instances==null||d.models.Length>10000||d.instances.Length>10000)throw new ArgumentException("非対応の洞窟壁描画形式");return d;}
 static bool Finite(float v){return !float.IsNaN(v)&&!float.IsInfinity(v);}static void Check(bool b,string s){if(!b)throw new ArgumentException(s);}
 public static Mesh BuildMesh(Geometry d){Check(d!=null&&d.positions!=null&&d.positions.Length>=9&&d.positions.Length%3==0&&d.positions.Length<=90000,"洞窟壁頂点数");int n=d.positions.Length/3;Check(d.normals!=null&&d.normals.Length==n*3&&d.colors!=null&&d.colors.Length==n*3&&d.uvs!=null&&d.uvs.Length==n*2&&d.triangles!=null&&d.triangles.Length%3==0,"洞窟壁属性数");var p=new Vector3[n];var normal=new Vector3[n];var color=new Color[n];var uv=new Vector2[n];for(int i=0;i<n;i++){for(int k=0;k<3;k++)Check(Finite(d.positions[i*3+k])&&Finite(d.normals[i*3+k])&&Finite(d.colors[i*3+k]),"非有限の壁頂点");Check(Finite(d.uvs[i*2])&&Finite(d.uvs[i*2+1]),"非有限の壁UV");p[i]=new Vector3(d.positions[i*3],d.positions[i*3+1],d.positions[i*3+2]);normal[i]=new Vector3(d.normals[i*3],d.normals[i*3+1],d.normals[i*3+2]);Check(normal[i].sqrMagnitude>.8f&&normal[i].sqrMagnitude<1.2f,"壁法線");color[i]=new Color(d.colors[i*3],d.colors[i*3+1],d.colors[i*3+2]);uv[i]=new Vector2(d.uvs[i*2],d.uvs[i*2+1]);}foreach(int i in d.triangles)Check(i>=0&&i<n,"壁の範囲外三角形");var mesh=new Mesh{name="CaveWallVisual",indexFormat=IndexFormat.UInt16};mesh.vertices=p;mesh.normals=normal;mesh.colors=color;mesh.uv=uv;mesh.triangles=d.triangles;mesh.RecalculateBounds();return mesh;}
 public static List<GameObject> Apply(string json,IReadOnlyDictionary<string,GameObject> byId,IReadOnlyDictionary<string,string> sourceHashes,Material rockMaterial,Transform mapRoot){
  Check(rockMaterial&&mapRoot,"岩材質とマップ原点が必要");Check(mapRoot.position==Vector3.zero&&mapRoot.rotation==Quaternion.identity&&mapRoot.lossyScale==Vector3.one,"マップ原点は単位行列");var d=Read(json);var models=new Dictionary<string,Model>();var meshes=new Dictionary<string,Mesh>();var prepared=new List<(Entry entry,Mesh mesh,Matrix4x4 matrix,Renderer[] old)>();var ids=new HashSet<string>();var existingVisuals=new HashSet<string>();foreach(var t in mapRoot.GetComponentsInChildren<Transform>(true))existingVisuals.Add(t.name);
  try{foreach(var model in d.models){Check(model!=null&&!String.IsNullOrEmpty(model.id)&&!models.ContainsKey(model.id)&&model.type=="cliff"&&sourceHashes.TryGetValue(model.type,out var hash)&&hash==model.sourceSha256,"洞窟壁の元部品SHA/ID");models.Add(model.id,model);meshes.Add(model.id,BuildMesh(model.render));}
   foreach(var e in d.instances){Check(e!=null&&!String.IsNullOrEmpty(e.instanceId)&&ids.Add(e.instanceId)&&e.type=="cliff"&&!e.replaceCollider&&models.ContainsKey(e.model),"洞窟壁の配置ID");Check(e.matrix!=null&&e.matrix.Length==16&&e.instanceTint!=null&&e.instanceTint.Length==3,"洞窟壁の配置行列");var matrix=new Matrix4x4();for(int k=0;k<16;k++){Check(Finite(e.matrix[k]),"非有限の配置行列");matrix[k]=e.matrix[k];}Check(matrix.determinant>0,"反転した配置行列");foreach(float c in e.instanceTint)Check(Finite(c)&&c>=0&&c<=4,"壁の色倍率");Check(byId.TryGetValue(e.instanceId,out var original)&&original,"洞窟壁の置換元が無い");Check(!existingVisuals.Contains("CaveWallVisual_"+e.instanceId),"描画補正は既に適用済み");var old=original.GetComponentsInChildren<Renderer>(true);bool found=!e.fitted;
    foreach(Transform child in mapRoot){if(e.fitted&&child.name=="CliffFit_"+e.instanceId){old=child.GetComponentsInChildren<Renderer>(true);found=true;}}Check(found&&old.Length>0,"加工済み壁Rendererが無い（先にCliffFitsMeshV1を適用）");
    var mesh=meshes[e.model];if(e.fitted){mesh=UnityEngine.Object.Instantiate(mesh);var p=mesh.vertices;var n=mesh.normals;var c=mesh.colors;var normalMatrix=matrix.inverse.transpose;for(int i=0;i<p.Length;i++){p[i]=matrix.MultiplyPoint3x4(p[i]);n[i]=normalMatrix.MultiplyVector(n[i]).normalized;c[i]=new Color(c[i].r*e.instanceTint[0],c[i].g*e.instanceTint[1],c[i].b*e.instanceTint[2]);}mesh.vertices=p;mesh.normals=n;mesh.colors=c;mesh.RecalculateBounds();}
    else Check(Mathf.Abs(Vector3.Dot(matrix.GetColumn(0),matrix.GetColumn(1)))<.0001f&&Mathf.Abs(Vector3.Dot(matrix.GetColumn(1),matrix.GetColumn(2)))<.0001f&&Mathf.Abs(Vector3.Dot(matrix.GetColumn(0),matrix.GetColumn(2)))<.0001f,"通常配置に剪断があります");prepared.Add((e,mesh,matrix,old));}
  }catch{foreach(var item in prepared)if(item.entry.fitted)UnityEngine.Object.DestroyImmediate(item.mesh);foreach(var mesh in meshes.Values)UnityEngine.Object.DestroyImmediate(mesh);throw;}
  foreach(var pair in meshes){bool used=false;foreach(var e in d.instances)if(!e.fitted&&e.model==pair.Key)used=true;if(!used)UnityEngine.Object.DestroyImmediate(pair.Value);}
  var result=new List<GameObject>();Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("洞窟壁の描画だけを補正");foreach(var item in prepared){foreach(var renderer in item.old){Undo.RecordObject(renderer,"壁描画の置換");renderer.enabled=false;}var go=new GameObject("CaveWallVisual_"+item.entry.instanceId);Undo.RegisterCreatedObjectUndo(go,"洞窟壁描画");go.transform.SetParent(item.entry.fitted?mapRoot:byId[item.entry.instanceId].transform,false);if(!item.entry.fitted){var local=byId[item.entry.instanceId].transform.worldToLocalMatrix*item.matrix;go.transform.localPosition=local.GetColumn(3);go.transform.localRotation=Quaternion.LookRotation(local.GetColumn(2),local.GetColumn(1));go.transform.localScale=new Vector3(local.GetColumn(0).magnitude,local.GetColumn(1).magnitude,local.GetColumn(2).magnitude);}go.AddComponent<MeshFilter>().sharedMesh=item.mesh;var rendererNew=go.AddComponent<MeshRenderer>();var sourceRenderer=item.old[0];var material=sourceRenderer.sharedMaterial?sourceRenderer.sharedMaterial:rockMaterial;rendererNew.sharedMaterial=material;rendererNew.shadowCastingMode=sourceRenderer.shadowCastingMode;rendererNew.receiveShadows=sourceRenderer.receiveShadows;var block=new MaterialPropertyBlock();sourceRenderer.GetPropertyBlock(block);rendererNew.SetPropertyBlock(block.isEmpty?null:block);result.Add(go);}Undo.CollapseUndoOperations(group);return result;
 }
}
}
#endif
